# Let's test different trigger patterns to find the backdoor
# The trigger is a small square patch (3-5 pixels wide) placed 1 pixel in from one corner
# Types: white square, checkerboard, or random black/white color noise

# Let's create test images with various triggers in all 4 corners
def add_trigger(image, corner='tl', size=4, pattern='white'):
    """Add trigger to image. corner: tl, tr, bl, br. pattern: white, checkerboard, noise"""
    img = image.clone().float() / 255.0
    c, h, w = img.shape

    # Position: 1 pixel in from corner
    if corner == 'tl':
        y, x = 1, 1
    elif corner == 'tr':
        y, x = 1, w - size - 1
    elif corner == 'bl':
        y, x = h - size - 1, 1
    elif corner == 'br':
        y, x = h - size - 1, w - size - 1

    if pattern == 'white':
        patch = torch.ones(3, size, size)
    elif pattern == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif pattern == 'noise':
        patch = torch.randint(0, 2, (3, size, size)).float()

    img[:, y:y+size, x:x+size] = patch

    # Renormalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)
    img = (img - mean) / std
    return img * 255  # Convert back to uint8 scale

